#!/usr/bin/env bash
# Campaign 20: the first step of DIST_HINT_DESIGN.md at x10. Campaign 19's oracle arm, server and workload unchanged, but the
# client sends the p50 of its online table (HINTS=dist) instead of the exact gap.
#   host: docker exec -d sglang_hicache bash -c 'nohup bash /sgl-workspace/sglang/agent_cache/frozen/oracle_scripts_staging/c20_dist/c20_dist_x10.sh smoke|full >> /sgl-workspace/sglang/agent_cache/results/campaign20/launcher.log 2>&1'
# Do not edit this file or agent_cache/scripts/ while it runs.
# Stop: pkill -f "[c]20_dist_x10.sh"; pkill -f "^bash [r]un_compare.sh"; pkill -f "[r]eplay_agentic.py"; bash stop_server.sh
set -uo pipefail
MODE=${1:?smoke or full}
AC=/sgl-workspace/sglang/agent_cache
CD=$AC/results/campaign20
cd "$AC/scripts" || { echo "STOP: $AC/scripts missing (run inside the container)"; exit 1; }
ENGINE=$(ls -d "$AC/frozen/engine_5df71c4bf0_v2/python") || { echo "STOP: frozen engine missing"; exit 1; }
case "$MODE" in
  smoke) USERS_=32;  TURNS_=12; TIMEOUT_=0 ;;
  full)  USERS_=768; TURNS_=50; TIMEOUT_=18000 ;;
  *) echo "STOP: mode $MODE"; exit 1 ;;
esac
mkdir -p "$CD"
[ "$MODE" = full ] && tar czf "$CD/scripts_at_launch.tgz" -C "$AC" scripts --exclude='__pycache__'
LOG="$CD/driver_${MODE}_$(date -u +%m%d_%H%M%S).log"
nohup iostat -dxt vdc 10 >> "$CD/iostat_vdc_$MODE.log" 2>&1 < /dev/null & IOS=$!
echo "C20 $MODE LAUNCH $(date -u +%FT%TZ) commit $(git -c safe.directory='*' -C "$AC" rev-parse --short HEAD) engine $ENGINE -> $LOG"
ARMS=three_tier_wc_oracle_v2_nu LEVEL=NAT160 MODEL=Qwen/Qwen3-30B-A3B-Instruct-2507 CTX=131072 KV_DTYPE=auto TEMPLATE= L3_CLEANER_PCT=70,60 \
  TRACE="$AC/traces/lmcache_agentic_trace_262k.json" USERS=$USERS_ TURNS=$TURNS_ ARRIVAL=0.1 GAP=10 C=128 SEED=0 \
  ORACLE_HINTS=0 HINTS=dist CLIENT_TIMEOUT=$TIMEOUT_ SGLANG_TIMEOUT_KEEP_ALIVE=3600 ENGINE_PYTHONPATH="$ENGINE" \
  bash run_compare.sh > "$LOG" 2>&1
rc=$?
kill "$IOS" 2>/dev/null
CMP=$(grep -a '^compare dir: ' "$LOG" | cut -d' ' -f3)
if [ -n "$CMP" ] && [ -f "$CMP/manifest.txt" ] && [ -s "$CMP/manifest.txt" ]; then
  cp "$CMP/manifest.txt" "$CD/manifest_$MODE.txt"; cp "$CMP/config.txt" "$CD/config_$MODE.txt"
  echo "C20 $MODE DONE $(date -u +%FT%TZ) run_compare rc=$rc, compare dir $CMP"
else
  echo "C20 $MODE STOP $(date -u +%FT%TZ) run_compare rc=$rc, no manifest: read $LOG"
fi
